CREATE OR REPLACE FUNCTION public.icash_operational_contact_current(p_account uuid, p_contact uuid, p_channel text, p_check_hour boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_operational_contacts;oc public.icash_owner_contacts;d public.icash_dnc_verification_receipts;src public.icash_dnc_verification_sources;stamp timestamptz;h integer;
begin
 if p_channel not in ('voice','sms') or p_check_hour is null then return false;end if;
 select * into c from public.icash_operational_contacts where id=p_contact and account_id=p_account and channel=p_channel;
 if not found then return false;end if;
 -- Same order as dispatch/STOP; locks protect real rows, never a UNION view.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform pg_advisory_xact_lock(hashtextextended(c.phone,74));
 perform pg_advisory_xact_lock(hashtextextended(c.contact_key,17));
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=c.owner_user_id for share;if not found then return false;end if;
 select * into c from public.icash_operational_contacts where id=p_contact and account_id=p_account and channel=p_channel for share;
 select * into oc from public.icash_owner_contacts where screening_id=c.screening_id and account_id=c.account_id for share;
 if not public.icash_lock_operational_dnc(p_account,p_contact) then return false;end if;
 select * into d from public.icash_dnc_verification_receipts where id=c.dnc_receipt_id;
 select * into src from public.icash_dnc_verification_sources where id=d.source_id;
 stamp:=clock_timestamp();
 if c.revoked_at is not null or c.eligibility_until<=stamp or oc.screening_id is null
 or c.source_hash is distinct from encode(sha256(convert_to(oc.result::text,'UTF8')),'hex')
 or not public.icash_operational_source_phone(oc.result,c.phone)
 or not exists(select 1 from public.icash_operation_spend o where o.operation_key=oc.operation_key and o.account_id=p_account and o.state in ('dispatched','settled'))
 or not exists(select 1 from public.icash_screening_jobs s where s.id=c.screening_id and s.account_id=p_account and s.state='complete' and s.snapshot->>'propertyId'=oc.result->>'propertyId' and coalesce(s.snapshot->>'practice','false')<>'true')
 or not exists(select 1 from public.icash_customer_identities where account_id=p_account and principal=c.sending_principal)
 or not exists(select 1 from public.icash_discovery_configs where account_id=p_account and contacts_enabled and data_rights_until>stamp)
 or d.id is null or d.phone is distinct from c.phone or d.contact_key is distinct from c.contact_key or d.clear is distinct from true or d.revoked_at is not null
 or d.checked_at>stamp or d.checked_at<stamp-interval '30 days' or d.expires_at<=stamp
 or (c.timezone_basis='source_record' and (d.contact_timezone is distinct from c.timezone or length(trim(coalesce(d.timezone_source_reference,'')))<12))
 or (c.timezone_basis='conservative_nanp_window' and (c.timezone<>'Pacific/Honolulu'
  or (c.channel='voice' and (c.local_start_hour<>9 or c.local_end_hour<>10 or not public.icash_conservative_voice_window_supported(c.phone)))
  or (c.channel='sms' and (c.local_start_hour<>10 or c.local_end_hour<>12 or not public.icash_conservative_nanp_window_supported(c.phone)))))
 or src.id is null or not src.enabled or src.expires_at<=stamp
 or not exists(select 1 from public.icash_timezone_names where name=c.timezone)
 or exists(select 1 from public.icash_text_suppressions where phone=c.phone)
 or exists(select 1 from public.icash_contact_suppressions where contact_key=c.contact_key)
 or exists(select 1 from public.icash_contact_permissions where account_id=p_account and screening_id=c.screening_id and phone=c.phone and revoked_at is not null)
 then return false;end if;
 if p_channel='sms' and not public.icash_owner_sms_quality_current(p_account,c.screening_id,c.phone) then return false;end if;
 h:=extract(hour from stamp at time zone c.timezone);
 return not p_check_hour or (h>=greatest(9,c.local_start_hour) and h<least(case when c.channel='voice' then 18 else 20 end,c.local_end_hour));
end $function$

CREATE OR REPLACE FUNCTION public.icash_dealmachine_observation_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='icash_owner_contacts' then
  if (exists(select 1 from public.icash_dealmachine_dnc_ingestions where screening_id=old.screening_id)
   or exists(select 1 from public.icash_dealmachine_dnc_rejections where screening_id=old.screening_id))
   and (tg_op='DELETE' or to_jsonb(new) is distinct from to_jsonb(old)) then raise exception 'Ingested owner-source binding is immutable';end if;
 elsif old.evidence_kind in ('national_provider_observation','national_phone_observation') then
  if tg_op='DELETE' or to_jsonb(new)-'revoked_at' is distinct from to_jsonb(old)-'revoked_at'
   or (old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at) then raise exception 'Derived DNC observation is immutable';end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

CREATE OR REPLACE FUNCTION icash_seller_recovery_private.original_contact_binding(p_account uuid, p_contact uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_operational_contacts;d public.icash_dnc_verification_receipts;i public.icash_dealmachine_dnc_ingestions;
 oc public.icash_owner_contacts;cost public.icash_cost_observations;o public.icash_operation_spend;reservation public.icash_credit_reservations;policy public.icash_dnc_verification_sources;stamp timestamptz;
begin
 if not public.icash_lock_operational_dnc_before_dm_observations(p_account,p_contact) then return false;end if;
 select * into c from public.icash_operational_contacts where id=p_contact and account_id=p_account;
 select * into d from public.icash_dnc_verification_receipts where id=c.dnc_receipt_id;
 if d.evidence_kind='legacy_record' then return true;end if;
 select * into i from public.icash_dealmachine_dnc_ingestions where screening_id=c.screening_id and account_id=p_account;
 select * into oc from public.icash_owner_contacts where screening_id=c.screening_id and account_id=p_account for share;
 select * into o from public.icash_operation_spend where operation_key=i.operation_key and account_id=p_account for share;
 select * into reservation from public.icash_credit_reservations where id=o.credit_reservation_id for share;
 perform 1 from public.icash_operation_rates where id=o.rate_id for share;
 perform 1 from public.icash_cost_observations where provider='dealmachine'
  and event_key in (i.operation_key,i.operation_key||':people',i.operation_key||':properties',i.operation_key||':deduplicated') order by event_key for share;
 select * into policy from public.icash_dnc_verification_sources where id=d.source_id;
 stamp:=clock_timestamp();
 return coalesce(i.screening_id is not null and oc.screening_id is not null and i.observations>0
  and i.source_id=d.source_id and i.source_hash=c.source_hash and i.source_hash=d.receipt_hash
  and i.source_hash=encode(sha256(convert_to(oc.result::text,'UTF8')),'hex') and i.operation_key=oc.operation_key and i.owner_user_id=c.owner_user_id
  and o.state in ('dispatched','settled') and i.provider_operation_hash=public.icash_dealmachine_operation_hash(o,reservation)
  and exists(select 1 from public.icash_operation_rates where id=o.rate_id and operation='owner_enrichment')
  and i.provider_cost_hash=public.icash_dealmachine_credit_manifest_hash(i.operation_key)
  and public.icash_dealmachine_saved_owner_result_valid(oc.result)
  and i.request_started_at=public.icash_dealmachine_owner_source_started_at(p_account,c.screening_id)
  and d.observation_provenance->>'accountId'=p_account::text and d.observation_provenance->>'screeningId'=c.screening_id::text
  and d.observation_provenance->>'providerOperationHash'=i.provider_operation_hash and d.observation_provenance->>'providerCostHash'=i.provider_cost_hash
  and d.observation_provenance->>'savedResultHash'=i.source_hash and d.observation_provenance->>'operationKey'=i.operation_key
  and d.checked_at=i.request_started_at and d.expires_at=i.original_expires_at and d.observation_recorded_at=i.ingested_at
  and policy.evidence_kind='national_provider_observation' and policy.observation_provider='dealmachine' and policy.observation_scope='national_only'
  and policy.enabled and policy.expires_at>stamp ,false);
end $function$

CREATE OR REPLACE FUNCTION public.icash_lock_operational_dnc(p_account uuid, p_contact uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_operational_contacts;old public.icash_operational_contacts;d public.icash_dnc_verification_receipts;
 f icash_seller_recovery_private.contact_refreshes;policy public.icash_dnc_verification_sources;stamp timestamptz;
begin
 select * into c from public.icash_operational_contacts where id=p_contact and account_id=p_account;
 select * into d from public.icash_dnc_verification_receipts where id=c.dnc_receipt_id;
 if d.evidence_kind is distinct from 'national_phone_observation' then return public.icash_lock_operational_dnc_before_phone_refresh(p_account,p_contact);end if;
 perform 1 from public.icash_dnc_verification_receipts where id=d.id for share;
 select * into policy from public.icash_dnc_verification_sources where id=d.source_id for share;
 select * into f from icash_seller_recovery_private.contact_refreshes where receipt_id=d.id and successor_contact_id=c.id and account_id=p_account for share;
 if not found then return false;end if;
 select * into old from public.icash_operational_contacts where id=f.original_contact_id for share;
 perform 1 from public.icash_operation_spend where operation_key=f.operation_key and account_id=p_account and state='settled' for share;if not found then return false;end if;
 if not icash_seller_recovery_private.original_contact_binding(p_account,old.id) then return false;end if;
 stamp:=clock_timestamp();
 return coalesce(row(old.account_id,old.screening_id,old.phone,old.contact_key,old.owner_user_id,old.source_hash,old.sending_principal,old.timezone,old.timezone_basis,old.local_start_hour,old.local_end_hour)
  is not distinct from row(c.account_id,c.screening_id,c.phone,c.contact_key,c.owner_user_id,c.source_hash,c.sending_principal,c.timezone,c.timezone_basis,c.local_start_hour,c.local_end_hour)
  and old.revoked_at is null and c.channel='sms' and (f.state='responded' or (f.state='processed' and f.outcome='revalidated')) and f.http_status between 200 and 299 and f.response_at>=f.requested_at
  and icash_seller_recovery_private.phone_response_valid(f.response,c.phone)
  and f.response#>'{data,0,matched}'='true'::jsonb and f.response#>'{data,0,do_not_call}'='false'::jsonb
  and d.receipt_hash=encode(sha256(convert_to(f.response::text,'UTF8')),'hex')
  and d.observation_provenance->>'refreshId'=f.id::text and d.observation_provenance->>'accountId'=p_account::text
  and d.observation_provenance->>'screeningId'=c.screening_id::text and d.observation_provenance->>'originalContactId'=old.id::text
  and d.observation_provenance->>'operationKey'=f.operation_key and d.observation_provenance->>'requestId'=f.request_id::text
  and d.checked_at=f.requested_at and d.observation_recorded_at=f.response_at
  and d.checked_at<=stamp and d.expires_at<=f.requested_at+interval '24 hours' and d.expires_at>stamp
  and policy.enabled and policy.expires_at>stamp and policy.evidence_kind='national_provider_observation'
  and policy.observation_provider='dealmachine' and policy.observation_scope='national_only'
  and f.requested_at+make_interval(secs=>policy.max_observation_age_seconds)>stamp
  and exists(select 1 from public.icash_dnc_verification_receipts original where original.id=old.dnc_receipt_id and original.source_id=d.source_id and original.clear and original.revoked_at is null),false);
end $function$
